static size_t /* <=== pad_to_4byte */ 
pad_to_4byte (size_t length)
{
    return (length+3) & ~3;
}

void  /* <=== write_guid */ 
write_guid (FILE *fp, GUID *guid)
{
    int j;
    fprintf (fp, "{ 0x%04x 0x%02x 0x%02x { ",
	     guid->data1, guid->data2, guid->data3);
    for (j = 0; j < 8; j++)
    {
	write_byte (fp, guid->data4[j]);
	fprintf (fp, " ");
    }
    fprintf (fp, "}");
}

void* /* <=== xmalloc */ 
xmalloc (size_t num, size_t size)
{
    size_t res;
    if (check_mul_overflow(num, size, &res))
        abort();

    void *ptr = malloc (res);
    if (!ptr
        && (size != 0))         /* some libc don't like size == 0 */
    {
        perror ("xmalloc: Memory allocation failure");
        abort();
    }
    return ptr;
}

